  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_audit_users
AFTER UPDATE OR DELETE ON users
FOR EACH ROW EXECUTE FUNCTION log_changes();', CURRENT_TIMESTAMP),
  ('database', 18, 'How do you query JSONB data efficiently in PostgreSQL?', 'Intermediate', '**
