    <div class="user-container">
      <mat-card>
        <mat-card-header>
          <mat-card-title>User Management</mat-card-title>
        </mat-card-header>
        
        <mat-card-content>
          <form [formGroup]="userForm" (ngSubmit)="onSubmit()">
            <mat-form-field appearance="fill">
              <mat-label>Name</mat-label>
              <input matInput formControlName="name">
              <mat-error *ngIf="userForm.get(''name'')?.errors?.[''required'']">
                Name is required
              </mat-error>
            </mat-form-field>
            
            <mat-form-field appearance="fill">
              <mat-label>Email</mat-label>
              <input matInput formControlName="email" type="email">
              <mat-error *ngIf="userForm.get(''email'')?.errors?.[''email'']">
                Invalid email
              </mat-error>
            </mat-form-field>
            
            <div class="form-actions">
              <button mat-raised-button color="primary" type="submit" 
                      [disabled]="userForm.invalid">
                Save User
              </button>
              <button mat-button type="button" (click)="onReset()">
                Reset
              </button>
            </div>
          </form>
        </mat-card-content>
      </mat-card>
      
      <app-user-list 
        [users]="users" 
        (userSelected)="onUserSelected($event)">
      </app-user-list>
      
      <app-user-detail 
        *ngIf="selectedUser" 
        [user]="selectedUser"
        (userUpdated)="onUserUpdated($event)">
      </app-user-detail>
    </div>
  `,
  styles: [`
    .user-container {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 20px;
      padding: 20px;
    }
    
    .form-actions {
      display: flex;
      gap: 10px;
      margin-top: 20px;
    }
    
    mat-form-field {
      width: 100%;
      margin-bottom: 15px;
    }
  `]
})
export class UserComponent {
  private fb = inject(FormBuilder);
  private userService = inject(UserService);
  
  users: any[] = [];
  selectedUser: any = null;
  
  userForm = this.fb.group({
    name: ['''', Validators.required],
    email: ['''', [Validators.required, Validators.email]]
  });
  
  ngOnInit() {
    this.loadUsers();
  }
  
  async loadUsers() {
    try {
      this.users = await this.userService.getUsers();
    } catch (error) {
      console.error(''Error loading users:'', error);
    }
  }
  
  async onSubmit() {
    if (this.userForm.valid) {
      try {
        const user = await this.userService.createUser(this.userForm.value);
        this.users.push(user);
        this.userForm.reset();
      } catch (error) {
        console.error(''Error creating user:'', error);
      }
    }
  }
  
  onReset() {
    this.userForm.reset();
    this.selectedUser = null;
  }
  
  onUserSelected(user: any) {
    this.selectedUser = user;
  }
  
  onUserUpdated(user: any) {
    const index = this.users.findIndex(u => u.id === user.id);
    if (index !== -1) {
      this.users[index] = user;
    }
  }
}

