export class UserListComponent {
  @Input() users: any[] = [];
  @Output() userSelected = new EventEmitter<any>();
  @Output() userDeleted = new EventEmitter<any>();
  
  selectUser(user: any) {
    this.userSelected.emit(user);
  }
  
  deleteUser(user: any) {
    this.userDeleted.emit(user);
  }
}

